Given two arrays represent Inorder and Preorder traversals of a binary tree, the task is to find the Postorder traversal.Example:Input: in[] = [4, 2, 5, 1, 3, 6]  pre[] = [1, 2, 4, 5, 3, 6]Output: 4 5 2 6 3 1Explanation: Traversals in the above example represents following tree: Try It YourselfTable of Content[Naive Recursive] Searching Root in Inorder - O(n²) Time and O(n) Space[Efficient Approach] Hash Map for Inorder Lookup - O(n) Time and O(n) Space[Naive Recursive] Searching Root in Inorder - O(n²) Time and O(n) SpaceThe idea is based on the properties of preorder and inorder traversals. In preorder traversal, the first element is always the root of the current subtree. By searching this root in the inorder traversal, the left and right subtrees can be identified. Take the first element of the current preorder range as the root  Find the root's index in the inorder traversal using linear search  Recursively process the left and right subtrees  Append the root to the postorder traversal 
            C++

    #include <bits/stdc++.h>
using namespace std;

// Find index of a value in inorder traversal
int search(vector<int> &in, int x)
{
    for (int i = 0; i < in.size(); i++)
    {
        if (in[i] == x)
            return i;
    }
    return -1;
}

// Recursive function to generate postorder traversal
void buildPostOrder(vector<int> &in, vector<int> &pre, int inStart, int inEnd, int preStart,
                    vector<int> &post)
{
    // No nodes in this subtree
    if (inStart > inEnd)
        return;

    // First element in preorder is the root
    int root = pre[preStart];

    // Find root position in inorder traversal
    int rootIndex = search(in, root);

    // Process left subtree
    buildPostOrder(in, pre, inStart, rootIndex - 1, preStart + 1, post);

    // Process right subtree
    buildPostOrder(in, pre, rootIndex + 1, inEnd, preStart + (rootIndex - inStart) + 1, post);

    // Add root after left and right subtree
    post.push_back(root);
}

// Function to return postorder traversal
vector<int> printPostOrder(vector<int> &in, vector<int> &pre)
{
    vector<int> post;

    buildPostOrder(in, pre, 0, in.size() - 1, 0, post);

    return post;
}

int main()
{
    vector<int> in = {4, 2, 5, 1, 3, 6};
    vector<int> pre = {1, 2, 4, 5, 3, 6};

    vector<int> post = printPostOrder(in, pre);

    for (int x : post)
        cout << x << " ";

    return 0;
}


